# Script S2. Winter nighttime minimum temperature metrics# Thermal Behavior of Crocodile Caves in Central Belize # Authors: Wynne, J.J., Shaffer, I.N., Roberts, J.# Script Author: J. Judson Wynne# R-Studio Version: 2025.05.1+513 (2025.05.1+513)# Input File# CrocCave_Data.xlsx# Output:# 1. Minimum nightly temperature per datalogger# 2. 5th percentile per datalogger# 3. 10th percentile per datalogger# Table 3. Distributional metrics of winter nighttime minimum temperaturesdat_winter <- dat %>% filter(DateTime >= winter_start, DateTime <= winter_end)night <- dat_winter %>% filter(Hour >= 19 | Hour <= 6) %>% mutate(Month = format(DateTime, "%Y-%m"), NightDate = as.Date(DateTime))night$NightDate[night$Hour <= 5] <- night$NightDate[night$Hour <= 5] - 1table3 <- night %>% group_by(Cave, Logger, NightDate) %>% summarize(NightlyMin = min(Temp, na.rm = TRUE), .groups = "drop") %>% summarize(Tmin = round(min(NightlyMin), 2), `5th %` = round(as.numeric(quantile(NightlyMin, 0.05)), 2), `10th %` = round(as.numeric(quantile(NightlyMin, 0.10)), 2), Median = round(median(NightlyMin), 2), .by = c(Cave, Logger)) %>% arrange(Cave, Logger)write.csv(table3, "Table3_NightlyMinima.csv", row.names = FALSE)